    public int width() { return trade != null ? 206 : this == INFO ? 212 : 276; }
    public int height() { return trade != null ? 196 : this == INFO ? 116 : 182; }
    public FloristPage target(int button) {
        if (trade != null) {
            int index = TRADES.indexOf(this);
            return button == 1 ? TRADES.get((index + 1) % TRADES.size()) : button == 2 ? TRADES.get((index + TRADES.size() - 1) % TRADES.size()) : null;
        }
        if (this == MAIN) return button == 0 ? INFO : button == 1 ? WATERING_CAN : null;
        if (this == INFO) return switch (button) { case 0 -> INFECTION; case 1 -> UNETTE; case 2 -> SELF; case 3 -> GARDENING; case 4 -> CONCIERGE; default -> null; };
        return button == 0 ? this == GARDENING ? GARDENING_2 : INFO : null;
    }
